WITH DeptAvg AS (SELECT DATE_FORMAT(s.pay_date, '%Y-%m') AS pay_month, e.department_id, AVG(s.amount) AS dept_avg FROM Salary s JOIN Employee e ON s.employee_id = e.employee_id GROUP BY pay_month, e.department_id), CompAvg AS (SELECT DATE_FORMAT(pay_date, '%Y-%m') AS pay_month, AVG(amount) AS comp_avg FROM Salary GROUP BY pay_month) SELECT d.pay_month, d.department_id, CASE WHEN d.dept_avg > c.comp_avg THEN 'higher' WHEN d.dept_avg < c.comp_avg THEN 'lower' ELSE 'same' END AS comparison FROM DeptAvg d JOIN CompAvg c ON d.pay_month = c.pay_month ORDER BY d.pay_month DESC, d.department_id ASC;
